    # Check if market was resolved (orderbook no longer exists)
    if (
        "orderbook" in error_str.lower()
        and "does not exist" in error_str.lower()
    ):
        self._logger.warning(
            f"{OPERATION_EMOJIS['warning']} Market is RESOLVED (orderbook not found). "
            f"Position {position.id} cannot be sold via orderbook. "
            f"Closing locally - you may need to REDEEM shares directly on Polymarket."
        )
        # Close the position since the market is resolved and can't be traded
        try:
            # Calculate final price with proper fallbacks (must be between 0 and 1, exclusive)
            # Priority: cur_price > calculated from current_value > avg_price > 0.5
            if position.cur_price is not None and 0 < position.cur_price < 1:
                final_price = position.cur_price
            elif (
                position.shares > 0
                and position.current_value
                and position.current_value > 0
            ):
                calculated = position.current_value / position.shares
                final_price = (
                    calculated if 0 < calculated < 1 else position.avg_price
                )
            else:
                final_price = (
                    position.avg_price if 0 < position.avg_price < 1 else 0.5
                )

            closed_position = await self._position_manager.close_position(
                position_id=position.id,
                final_price=final_price,
                market=market,
            )
            self._logger.info(
                f"{OPERATION_EMOJIS['success']} Position {position.id} closed "
                f"due to market resolution (orderbook not found)"
            )
            return SellResult(
                trade=None,
                position=closed_position,
                realized_pnl=0.0,  # Can't determine PnL without market price
                success=True,  # Position closed successfully
                error_message="Market resolved - position closed locally. Redeem shares on Polymarket.",
            )
        except Exception as close_error:
            self._logger.error(
                f"{OPERATION_EMOJIS['error']} Failed to close position {position.id} "
                f"after market resolution: {close_error}"
            )

    return SellResult(
        trade=None,
        position=position,
        success=False,
        error_message=f"Unexpected error: {e}",
    )

